package com.smartdairy.service;
import com.smartdairy.entity.MilkCollection; import com.smartdairy.repository.MilkCollectionRepository; import java.time.LocalDate; import java.util.*;
public class MilkCollectionService {private final MilkCollectionRepository repo=new MilkCollectionRepository();
 public int create(MilkCollection m)throws Exception{validate(m);m.setAmount(calculateAmount(m.getQuantity(),m.getRate()));return repo.save(m);} public double calculateAmount(double quantity,double rate){return Math.round(quantity*rate*100.0)/100.0;} public List<MilkCollection> recent(int limit)throws Exception{return repo.findRecent(Math.max(1,Math.min(limit,100)));} public double totalQuantity()throws Exception{return repo.totalQuantity();} public double totalAmount()throws Exception{return repo.totalAmount();} public long totalEntries()throws Exception{return repo.totalEntries();}
 private void validate(MilkCollection m){if(m==null||m.getCollectionDate()==null)throw new IllegalArgumentException("Collection date is required");if(m.getCollectionDate().isAfter(LocalDate.now()))throw new IllegalArgumentException("Collection date cannot be in the future");if(m.getSupplierName()==null||m.getSupplierName().trim().isEmpty())throw new IllegalArgumentException("Supplier name is required");if(m.getQuantity()<=0||m.getRate()<0)throw new IllegalArgumentException("Quantity must be positive and rate cannot be negative");if(m.getFat()<0||m.getSnf()<0)throw new IllegalArgumentException("Fat/SNF cannot be negative");if(!"MORNING".equals(m.getShift())&&!"EVENING".equals(m.getShift()))throw new IllegalArgumentException("Invalid shift");}
}
